import {useEffect,useRef,useState} from "react";
import {Button,ErrorState,LoadingState,Table} from "@xcss/web/admin-ui";
import {t} from "@xcss/web/admin-ui/i18n";
import {errorRequestId,useAdminApplication} from "@xcss/web/admin-shell";
import {CURRENT_API_PREFIX,isOperation,isRecentOperations,isClientAuthorization,isDevice,type DeviceInfo,type OperationPage,type Ticket} from "./api";
import {AccessEditor} from "./AccessEditor";
import {integrationLabel,roleLabel} from "./DeviceInstances";
export function ClientWorkspace({device,devices,refreshSignal,ticket,changed}:{device:DeviceInfo;devices:DeviceInfo[];refreshSignal:number;ticket:Ticket|null;changed():void}){
 const{client}=useAdminApplication();const diagnosticKey=useRef<string|null>(null);const[history,setHistory]=useState<OperationPage|null>(null);const[failure,setFailure]=useState<{requestId?:string}|null>(null);const[busy,setBusy]=useState(false);const[revision,setRevision]=useState(0);const[authorization,setAuthorization]=useState<string|null>(ticket?.token??null);const[name,setName]=useState(device.name);const[confirmRevoke,setConfirmRevoke]=useState(false);
 useEffect(()=>{let active=true;const controller=new AbortController();let timer:number|undefined;async function load(){try{const value=await client.request(`${CURRENT_API_PREFIX}/devices/${device.id}/tasks?recent=50`,isRecentOperations,{signal:controller.signal});if(active){setHistory({operations:value,next_cursor:null,previous_cursor:null});setFailure(null)}}catch(error){if(active)setFailure({requestId:errorRequestId(error)})}finally{if(active)timer=window.setTimeout(load,5000)}}void load();return()=>{active=false;controller.abort();if(timer!==undefined)clearTimeout(timer)}},[client,device.id,refreshSignal,revision]);
 async function readDiagnostics(){if(busy)return;setBusy(true);setFailure(null);try{await client.request(`${CURRENT_API_PREFIX}/devices/${device.id}/tasks`,isOperation,{method:"POST",headers:{"Idempotency-Key":diagnosticKey.current??(diagnosticKey.current=crypto.randomUUID())},body:JSON.stringify({kind:"read_diagnostics"})});diagnosticKey.current=null;setRevision(v=>v+1);changed()}catch(error){setFailure({requestId:errorRequestId(error)})}finally{setBusy(false)}}
 async function revealAuthorization(){if(busy)return;setBusy(true);try{const value=await client.request(`${CURRENT_API_PREFIX}/devices/${device.id}/authorization`,isClientAuthorization);setAuthorization(value.authorization_code)}catch(error){setFailure({requestId:errorRequestId(error)})}finally{setBusy(false)}}
 async function rename(){if(busy)return;setBusy(true);try{await client.request(`${CURRENT_API_PREFIX}/devices/${device.id}`,isDevice,{method:"PATCH",body:JSON.stringify({name})});changed()}catch(error){setFailure({requestId:errorRequestId(error)})}finally{setBusy(false)}}
 async function revoke(){if(busy)return;setBusy(true);try{await client.request(`${CURRENT_API_PREFIX}/devices/${device.id}/revoke`,(v):v is undefined=>v===undefined,{method:"POST"});setAuthorization(null);setConfirmRevoke(false);changed()}catch(error){setFailure({requestId:errorRequestId(error)})}finally{setBusy(false)}}
 return <section className="xcss-content-stack"><h2>{device.name}</h2><p>{integrationLabel(device)}</p><p>{t("实例角色和控制权限由服务端管理，地址由被控端上报。在原生客户端绑定实例后，从授权列表发起连接。","The server manages instance roles and permissions; controlled hosts report their addresses. Bind an instance in the native client and connect from its allowed hosts.")}</p><form className="xcss-actions" onSubmit={event=>{event.preventDefault();void rename()}}><label>{t("实例名称","Instance name")}<input value={name} maxLength={32} required onChange={event=>setName(event.target.value)}/></label><Button type="submit" disabled={busy||!name.trim()||name.trim()!==name||[...name].length>32}>{t("保存名称","Save name")}</Button></form>
 <div className="xcss-actions"><Button disabled={busy||device.revoked} onClick={()=>{if(authorization)setAuthorization(null);else void revealAuthorization()}}>{authorization?t("隐藏授权码","Hide enrollment code"):t("显示授权码","Show enrollment code")}</Button>{!device.revoked&&(confirmRevoke?<><Button disabled={busy} onClick={()=>void revoke()}>{t("确认撤销凭据","Confirm credential revocation")}</Button><Button disabled={busy} onClick={()=>setConfirmRevoke(false)}>{t("取消","Cancel")}</Button></>:<Button disabled={busy} onClick={()=>setConfirmRevoke(true)}>{t("撤销客户端凭据","Revoke client credentials")}</Button>)}</div>
 {authorization&&<div role="status"><p>{t("实例授权码：","Instance enrollment code:")}</p><code>{authorization}</code></div>}
 <dl><dt>{t("角色","Role")}</dt><dd>{roleLabel(device)}</dd><dt>{t("运行方式","Execution mode")}</dt><dd>{t("RustDesk 进程内嵌入","Embedded in RustDesk")}</dd><dt>{t("RustDesk 版本","RustDesk version")}</dt><dd>{device.diagnostics?.rustdesk_version??"—"}</dd></dl>
 {device.role==="controlled"&&<div><h3>{t("被控端上报地址","Reported host addresses")}</h3>{device.addresses.length===0?<p>{t("尚未上报可连接地址","No connection addresses reported")}</p>:<ul>{device.addresses.map(address=><li key={`${address.host}:${address.port}`}><code>{address.host.includes(":")?`[${address.host}]`:address.host}:{address.port}</code></li>)}</ul>}<p>{t("最近上报：","Last report: ")}{device.addresses_at_micros===null?"—":new Date(device.addresses_at_micros/1000).toISOString()}</p><p>{t("离线或超过 45 秒的地址不会下发给控制端。","Addresses are omitted from controller lists when offline or older than 45 seconds.")}</p></div>}
 <AccessEditor device={device} devices={devices} changed={changed}/>
 <div className="xcss-actions"><Button disabled={busy||!device.registered||device.revoked} onClick={()=>void readDiagnostics()}>{t("读取主机诊断","Read host diagnostics")}</Button></div>
 {failure&&<ErrorState requestId={failure.requestId}>{t("操作未能完成，请刷新任务记录核对。","The operation did not complete. Refresh the task history to check.")}</ErrorState>}
 <h3>{t("最近 50 条任务记录","Latest 50 tasks")}</h3>{history===null?<LoadingState>{t("正在读取任务…","Loading tasks…")}</LoadingState>:<><Table><thead><tr><th>{t("时间","Time")}</th><th>{t("操作","Action")}</th><th>{t("状态","State")}</th><th>{t("结果","Result")}</th></tr></thead><tbody>{history.operations.map(op=><tr key={op.operation_id}><td>{op.created_at_server}</td><td>{op.action}</td><td>{op.state}</td><td><pre>{JSON.stringify(op.reconciliation??op.result,null,2)}</pre></td></tr>)}</tbody></Table></>}
 </section>;
}
